-- Sync the menu to menu_items_4.csv (305 dishes, all 15 stalls). Two dishes are
-- renamed in place (Mr.Mouslache garlic chicken, Nui Noodles MAMA) so their ingredients, tags
-- and order history carry over. CSV has no ingredients/tags/allergens/spice_level, so existing
-- dishes keep theirs. Sai Nua's choice-of-meat dishes stay non-halal (the stall offers pork)
-- even though the CSV marks them halal. Every stall still has dishes, so no vendor is removed.
update public.menu_items m set
  name = v.name, name_th = v.name_th, description = v.description, price = v.price,
  category = v.category, is_halal = v.is_halal, is_vegetarian = v.is_veg, is_jay = v.is_jay,
  image_url = v.image_url, is_available = true, updated_at = now()
